INSERT INTO `company` (`id`, `first_name`, `second_name`, `age`, `phone`, `job_position`, `company_name`, `description`, `file`, `img`, `email`, `password`, `status`, `created_at`, `updated_at`) VALUES
(6, 'Alina', 'Utkirova', 22, '+998911633204', 'Founder', 'BRIGHTBRIDGE LLC', 'A smart job-matching platform designed to connect students with the right career opportunities while helping companies find skilled candidates efficiently. Our mission is to bridge the gap between education and employment by providing students with the tools, training, and real-world experience they need to succeed.', 'upl/certs/1739348046_privacy.PDF', 'upl/logo/1739779310_vvvvvv.jpg', 'Autkirov@gmail.com', 'admin3204', 1, '2025-02-04 16:18:09', '2025-07-30 12:22:13'),
(10, 'Abbos', 'Utkirov', 34, '+998911633204', 'Mentor', 'IT Park', 'IT Park Today\r\nOn July 24, 2019 the first IT Park in the Republic of Uzbekistan opened its doors in Tashkent. In a given short amount of time, IT Park has already brought its first fruits in the form of 28 new startups, created dozens of projects in the field of information technology, as well as trainings, workshops and meetings to encourage the youth of our country, their interest in this area and develop computer literacy among the population.\r\n\r\nIT Park is a complex of facilities, buildings and structures designed to ensure the startup and market access, an extraterritorial free economic zone for IT companies, including integration with scientific and educational organizations. It is a place where active and talented people in the field IT will have a real chance to transform their ideas into real business projects through accounting, legal, marketing and educational support.', 'upl/certs/1739338845_litsenziya-itpark.jpg', 'upl/logo/1739338845_Без_названия.png', 'autkirov2@gmail.com', '1234567', 0, '2025-02-12 05:40:45', '2025-02-12 07:29:17'),
(13, 'IT park', 'IT park', 19, '+998909099999', 'IT park Mentor', 'IT Park', 'Job description\r\nIT Park Uzbekistan is Looking for Ambassadors from MDIS Tashkent! Are you passionate about technology, innovation, and community building? IT Park Uzbekistan is looking for motivated students from MDIST to become IT Park Ambassadors\r\n\r\nResponsibility\r\nResponsibilities as an Ambassador: Organize and promote IT Park events at MDIST; Encourage students to participate in IT Park activities.\r\nQualifications\r\nWho Can Apply? Any motivated student from MDIST with a passion for tech, events, and community building!\r\nBenefits\r\nBenefits of Becoming an IT Park Ambassador: Leadership & event management experience Networking with IT professionals', 'upl/certs/1751958678_1740469563_Без_названия_-_Copy.png', 'upl/logo/1751958678_1740469563_Без_названия_-_Copy.png', 'abboskahotcom@gmail.com', 'Onlyforkahoot', 0, '2025-07-08 07:11:18', '2025-07-08 07:11:18');

