(23, 'Javohirjon', 'Asatullayev', '22', 'asatullayevjavohirjon@gmail.com', 'Falcon1.', '+998997023750', 'Cybersecurity Specialist / Sysadmin', 'upl/resumes/1757504357_rezume_asatullayev_javohir.docx', 'upl/candidates/1757504357_1000010838.jpg', 'Networking (TCP/IP, DHCP, DNS),System Administration (Windows/Linux Server),Firewall Configuration & Management  Cybersecurity Basics (SIEM, wazuh)  Troubleshooting & Problem Solving  Virtualization (VMware, VirtualBox, Hyper-V)  Docker & Containerization  Teamwork & Communication Skills & Attention to Detail', 1, 'Tashkent, Chilonzor 20 21 99', 1500.00, '2025-09-10 11:39:17', '2025-09-10 11:40:36');

