INSERT INTO `news` (`id`, `title`, `about`, `info`, `img`, `youtube`, `cat_id`, `created_at`, `updated_at`) VALUES
(1, '🎉 Exciting Field Trip to Safia Café & Bakery Factory', '<p><strong>Dear MDIST Students,</strong> 👋</p><p>MDIS Tashkent is thrilled to invite you to an exciting field trip to the <strong>“Safia Café & Bakery Factory”</strong> in Tashkent. 🏙️</p>', '<p>During this visit, you will meet <strong>Bekhzod Samigjanov</strong>, the director of the bakery, and <strong>Madina Ayyupova</strong>, the founder of the project. They will share the secrets behind Safia’s delicious pastries and cakes 🍰🥐 and their inspiring journey to success in the business world. 🚀</p><p><strong>📅 Date:</strong> February 25, 2025 (Tuesday)</p><p><strong>⏰ Time:</strong> 10:00 AM</p><p><strong>📍 Venue:</strong> Meeting point at 9:45 AM before departure to Safia Bakery, located at 256 Faziltepa Street, Tashkent</p><p><strong><span style=\"color: red;\">⚠️ Seats are limited to 25 students.</span></strong></p><p>📝 Please register by <strong>February 24, 2025</strong> via the following Google Form: <a href=\"#\">Registration Link</a></p><p>Don’t miss this opportunity to learn, network 🤝, and make your MDIST journey even more memorable! 🌟</p><p><strong>Best regards,</strong><br>MDIS Tashkent Team 🎓</p>', 'upl/blog/18181.jpg', '0', 1, '2025-02-01 09:38:12', '2025-02-10 14:06:04'),
(6, '💡 Business & Start-Up Workshop 🚀', 'Are you passionate about business or have a great start-up idea? Join us at the <strong>Business Incubator Center</strong>', '<p>Are you passionate about business or have a great start-up idea? Join us at the <strong>Business Incubator Center</strong> for an <strong>introductory workshop</strong> where you\'ll gain valuable insights into developing business ideas, strategic planning, and start-up growth.</p><p>📍 <strong>Venue:</strong> Business Incubator (4th Floor) <br>⏰ <strong>Time:</strong> 15:00 <br>🗓 <strong>Date:</strong> 07.02.2025 (Friday)</p><h3>Why Attend?</h3><ul>  <li>🔺 Gain essential business knowledge</li>  <li>🔺 Learn from experienced mentors</li>  <li>🔺 Expand your network & opportunities</li></ul><p>✨ <strong>Don’t miss out—join us and take the first step towards success!</strong></p><p>📱 <strong>Contact us:</strong> <br><a href=\"https://t.me/Mdistsc\" target=\"_blank\">@Mdistsc</a> | <a href=\"https://t.me/Mdist_business\" target=\"_blank\">@Mdist_business</a></p', 'upl/blog/1739077803.jpg', 'https://youtu.be/DhUPZNbifAw', 1, '2025-02-02 09:38:12', '2025-02-09 05:10:03'),
(7, 'Enhance Your Career Prospects with the MDIST Professional Development Centre and Business Incubation Centre!', '📢 Join our upcoming session on Crafting an Effective CV to stand out in the competitive job market.', 'Agenda Highlights:\r\n\r\nProfessional Formatting: Learn how to structure your CV for clarity and professionalism.\r\nJob-Specific Customization: Tailor your CV content to align with job requirements effectively.\r\nPowerful Language: Discover how to use impactful keywords and action verbs.\r\nJob Care Profile: Create and optimize your profile on a free platform for better job opportunities.\r\n\r\n🗓 Date: February 13, 2025\r\n⏰ Time: 12:30\r\n📍 Venue: B110\r\n\r\n🔗 Register here (https://forms.gle/3FB9jgBLmcWgabvj9) \r\n\r\nThis session is brought to you by the MDIS Tashkent Professional Development Centre in collaboration with the Business Incubation Centre, ensuring you get the tools and resources to jumpstart your career!\r\n\r\n📌 Scan the QR code to register and access additional details. \r\n\r\nhttps://t.me/PDC_MDIST\r\n\r\n📱  @Mdistsc  \r\n📱  @Mdist_business', 'upl/blog/1739047668_announc-mdist.png', 'https://youtu.be/kn-WxPj1Ccw', 3, '2025-02-08 20:47:48', '2025-02-08 20:47:48'),
(9, '📢 IT Park Uzbekistan is Looking for Ambassadors from MDIS Tashkent! 🚀', 'Why Become an IT Park Ambassador? ✅ Gain leadership and organizational experience ✅ Be the bridge between IT Park and MDIST students ✅ Network with industry professionals and tech experts ✅ Boost your resume with a prestigious role Your Responsibilities as an Ambassador: 🔹 Organize and promote IT Park events at MDIST 🔹 Encourage students to participate in IT Park activities 🔹 Spread awareness about IT Park\'s opportunities 🔔 Who Can Apply? 💡 Any motivated student from MDIST with a passion for tech, events, and community building! 📅 Apply Now via this link: <a href\"link\"> http://brightbridge.uz/category/3 </a> 📍 For more details, contact: [Your Contact Info] Join us and be a part of Uzbekistan’s growing tech ecosystem! 🚀💻', 'Why Become an IT Park Ambassador?✅ Gain leadership and organizational experience✅ Be the bridge between IT Park and MDIST students✅ Network with industry professionals and tech experts✅ Boost your resume with a prestigious roleYour Responsibilities as an Ambassador:🔹 Organize and promote IT Park events at MDIST🔹 Encourage students to participate in IT Park activities🔹 Spread awareness about IT Park\'s opportunities🔔 Who Can Apply?💡 Any motivated student from MDIST with a passion for tech, events, and community building!📅 Apply Now via this link: http://brightbridge.uz/category/3 📍 For more details, contact: [Your Contact Info]Join us and be a part of Uzbekistan’s growing tech ecosystem! 🚀💻', 'upl/blog/1739339232_gJpvWrSwRidA6g54JVZ0AskSTMhCuZ9etyssWL87.jpeg', '0', 3, '2025-02-12 05:47:12', '2025-02-12 10:44:14'),
(10, 'Uzbekistan-2030 Strategy: Key Priorities', 'The Uzbekistan-2030 Strategy focuses on five key priorities for national development:', '<h2>Guest Lecturer Announcement</h2>\r\n    <p><strong>Dear Students,</strong></p>\r\n\r\n    <p>We are pleased to announce that <strong>Mr. Eldor Tulyakov</strong> will be joining us as a guest lecturer for an exclusive session. This is a valuable opportunity to gain insights from an experienced professional and deepen your understanding of the subject.</p>\r\n\r\n    <p><strong>Speaker:</strong> Mr. Eldor Tulyakov <br>\r\n    <strong>Date:</strong> 17th February, 2025 <br>\r\n    <strong>Time:</strong> 11:00 AM <br>\r\n    <strong>Venue:</strong> B312 Room</p>\r\n\r\n    <h3>Uzbekistan-2030 Strategy: Key Priorities</h3>\r\n    <ul>\r\n        <li><strong>Empowering People –</strong> Creating conditions for individuals to reach their full potential.</li>\r\n        <li><strong>Economic Growth –</strong> Ensuring sustainable development and prosperity.</li>\r\n        <li><strong>Environmental Protection –</strong> Conserving water resources and promoting sustainability.</li>\r\n        <li><strong>Good Governance –</strong> Strengthening the rule of law and public administration.</li>\r\n        <li><strong>Peace & Security –</strong> Upholding stability and a safe society.</li>\r\n    </ul>\r\n\r\n    <p>This strategy aims to drive progress and innovation for a better future.</p>\r\n<p>\r\n        <strong></p>\r\n <a href=\"https://www.mdis.uz/en/news/gostevaja-lektsija-po-ekonomicheskomu-razvitiju-s-eldorom-tuljakovym-v-biznes-inkubatore-mdist\" target=\"_blank\">\r\n            Find out more on MDIST Official Website \r\n        </a> <br>\r\n    </p>\r\n\r\n    <p>🌐 <a href=\"https://brightbridge.uz\" target=\"_blank\">BRIGHTBRIDGE.UZ</a> <br>\r\n    🖥 <a href=\"https://brightbridge.uz/logup\" target=\"_blank\">Register now</a> and shape your future with us!</p>\r\n\r\n    <p>📱 <a href=\"https://t.me/jobcare.uz/\" target=\"_blank\">Telegram</a> <br>\r\n    📱 <a href=\"https://instagram.com/brightbridge\" target=\"_blank\">Instagram</a> <br>\r\n    📱 <a href=\"https://linkedin.com/company/brightbridge\" target=\"_blank\">LinkedIn</a></p>\r\n\r\n    <p>✉️ <a href=\"mailto:brightbridge_support@gmail.com\">@brightbridge_support</a></p>', 'upl/blog/1739621285_1.png', '0', 5, '2025-02-15 12:08:05', '2025-03-03 16:27:02'),
(14, 'Business Communication Workshop', 'MDIST Professional Development Centre and Business Incubation Centre organized a Business Communication Workshop for students preparing for Intern Fair Day', '<h2>\n    MDIST Professional Development Centre and Business Incubation Centre \n    organized a Business Communication Workshop for students preparing for Intern Fair Day\n</h2>\n\n<p><strong>Dear Students,</strong></p>\n\n<p>\n    We are pleased to announce that <strong>Led by Lecturer Abbos Utkirov</strong>, \n    the session equipped students with essential skills to enhance their professional communication \n    and writing abilities. Watch this recorded training and bring your CV:\n</p>\n\n<p>\n    <strong>📅 Date:</strong> 21st February, 2025 <br>\n    <strong>⏰ Time:</strong> 14:00 <br>\n    <strong>📍 Venue:</strong> LRC <br>\n    <strong>👔 Dress Code:</strong> Formal or Semi-formal\n</p>\n\n<h3>Business Communication: CW Writing Techniques</h3>\n\n<ul>\n    <li><strong>Professional Formatting –</strong> Structuring CVs for clarity and professionalism.</li>\n    <li><strong>Job-Specific Customization –</strong> Tailoring content to match job needs.</li>\n    <li><strong>Powerful Language –</strong> Using strong keywords and action verbs.</li>\n    <li><strong>Job Care Profile –</strong> Opening a profile for better opportunities (Free Platform).</li>\n</ul>\n\n<p>\n    <a href=\"https://drive.google.com/drive/u/1/folders/1nO5_subHI1n1zWd5LuRecKTeDd4DdO5j\" target=\"_blank\">\n        📥 Download materials\n    </a> and shape your future with us!\n</p>\n\n<p>\n    <a href=\"https://www.mdis.uz/en/news/business-communication-workshop-for-intern-fair-day-preparation\" target=\"_blank\">\n        🌍 Find out more on MDIST Official Website\n    </a>\n</p>\n\n<p>\n    🌐 <a href=\"https://brightbridge.uz\" target=\"_blank\">BRIGHTBRIDGE.UZ</a> <br>\n</p>\n\n<p>\n    📱 <a href=\"https://t.me/PDC_MDIST\" target=\"_blank\"> PDC Telegram</a> <br>\n    📱 <a href=\"https://t.me/jobcare.uz/\" target=\"_blank\">Brightbridge Telegram</a> <br>\n    📱 <a href=\"https://instagram.com/brightbridge\" target=\"_blank\">Instagram</a> <br>\n    📱 <a href=\"https://linkedin.com/company/brightbridge\" target=\"_blank\">LinkedIn</a>\n</p>\n\n<p>✉️ <a href=\"mailto:brightbridge_support@gmail.com\">brightbridge_support@gmail.com</a></p>\n', 'upl/blog/1739899688_thumb777.png', 'https://youtu.be/P-Fi_94Tuh8', 1, '2025-02-18 17:28:08', '2025-03-03 16:10:45'),
(15, 'Demo Day', 'MDIST and IT Park Uzbekistan Empower Student Startups', 'The Management Development Institute of Singapore in Tashkent (MDIST) and IT Park Uzbekistan hosted a Demo Day to support student-led startups and innovations. The event featured speeches from key industry leaders, including MDIST Vice Rector Dildora Ishankhodjaeva and IT Park representative Doniyor Yusupov, highlighting the role of startups in economic growth.\r\n\r\nPromising projects such as DAMDAM, Your Service, ratemyedu.org, FitLook, and Habitat were presented by talented students. A panel of experts, including Abbos Utkirov (MDIST, Brightbridge), Rano Sidikova (Plug and Play), Bekhzod Abdullaev (IT Park Ventures), and Farrukh Makhsumov (C-Space Ventures), evaluated the startups.\r\n<strong>Led by Lecturer Abbos Utkirov</strong>\r\n\r\nIT Park Uzbekistan continues to foster innovation by providing mentorship, investment opportunities, and resources for young entrepreneurs to scale their projects to global markets. Find more details here: <a href=\"https://it-park.uz/en/itpark/news/mdist-and-it-park-uzbekistan-support-student-initiatives\" target=\"_blank\">\r\n           <strong> IT Park Uzbekistan</strong>\r\n        </a> \r\n</p> <p> 📱 <a href=\"https://it-park.uz/en/itpark/news/mdist-and-it-park-uzbekistan-support-student-initiatives\" target=\"_blank\"> IT Park</a> <br> 📱 <a href=\"https://t.me/jobcare.uz/\" target=\"_blank\">Brightbridge Telegram</a> <br> 📱 <a href=\"https://instagram.com/brightbridge\" target=\"_blank\">Instagram</a> <br> 📱 <a href=\"https://linkedin.com/company/brightbridge\" target=\"_blank\">LinkedIn</a> </p> <p>✉️ <a href=\"mailto:brightbridge_support@gmail.com\">brightbridge_support@gmail.com</a></p>', 'upl/blog/1740582433_itttttttttt_park7777777777777777777777777.jpg', '0', 3, '2025-02-26 15:07:13', '2025-02-26 15:24:17'),
(16, 'Internship Fair Day Highlights', 'MDIST Professional Development Centre and Business Incubation Centre organized a Business Communication Workshop for students preparing for Intern Fair Day', 'Specialists had a great pleasure while having a conversation with students and graduates. They learned about internship and career development\r\n🤩 The atmosphere was buzzing with enthusiasm as students shared their resumes, practiced their elevator pitches, and engaged in insightful conversations with recruiters. It was inspiring to see so many motivated individuals ready to take the next step!\r\n\r\n🤝 We’d express our sincere gratitude to all the companies that participated and to everyone who attended. Your dedication to fostering connections and supporting our future professionals is invaluable! This event truly showcased the potential of our future leaders!\r\n\r\n<p>\r\n        📱 <a href=\"https://t.me/PDC_MDIST\" target=\"_blank\"> PDC Telegram</a> <br>\r\n        📱 <a href=\"https://t.me/jobcare.uz/\" target=\"_blank\">Brightbridge Telegram</a> <br>\r\n        📱 <a href=\"https://instagram.com/brightbridge\" target=\"_blank\">Instagram</a> <br>\r\n        📱 <a href=\"https://linkedin.com/company/brightbridge\" target=\"_blank\">LinkedIn</a>\r\n    </p>', 'upl/blog/1740596002_Purple_And_White_Bold_Career_Fair_Instagram_Post_(1).png', 'https://youtu.be/rNGRZZ7u65s', 5, '2025-02-26 18:53:22', '2025-02-26 21:26:45'),
(17, 'Beeline Uzbekistan is looking for young talents! / Компания Beeline Uzbekistan в поиске молодых талантов!', 'Procurement Department', '✅ Flexible work schedule / Гибкий график<br> <strongWe are looking for candidates who: / Мы ждем, что ты::</strong> ✔ Are final-year students / Студент последних курсов\r\n✔ Have fluency in English (Turkish is a plus) / Свободное владение английским языком (знание турецкого является плюсом)\r\n✔ Are proficient in MS Excel and PowerPoint / Опытный пользователь MS Excel и PowerPoint\r\n✔ Have strong teamwork and communication skills / Умеешь работать в команде и коммуникабелен <br> <strong>👉🏼 Ready to join our team? / Готов стать частью нашей команды?</strong> Send your resume and motivation letter (“Why I want to work at Beeline Uzbekistan”) to graduate@beeline.uz\r\n/ Отправь свое резюме и мотивационное письмо («Почему я хочу работать в Beeline Uzbekistan») на почту: graduate@beeline.uz <br> <strong>🗓 Application deadline::</strong> February 28, 2025 / Заявки принимаются до 28 февраля 2025 года </p> <h3>🏆 Beeline Uzbekistan – your career starts here! / Beeline Uzbekistan — старт твоей карьеры! </h3> \r\n <p> 📱 <a href=\"https://brightbridge.uz/job_details/37\" target=\"_blank\"> See job details</a> <br>\r\n  📱 <a href=\"https://t.me/PDC_MDIST\" target=\"_blank\"> PDC Telegram</a> <br> 📱 <a href=\"https://t.me/jobcare.uz/\" target=\"_blank\">Brightbridge Telegram</a> <br> 📱 <a href=\"https://instagram.com/brightbridge\" target=\"_blank\">Instagram</a> <br> 📱 <a href=\"https://linkedin.com/company/brightbridge\" target=\"_blank\">LinkedIn</a> </p> <p>✉️ <a href=\"mailto: graduate@beeline.uz \"> graduate@beeline.uz </a></p>', 'upl/blog/1740604960_photo_2025-02-27_02-20-36.jpg', '0', 5, '2025-02-26 21:22:40', '2025-02-26 21:31:23'),
(19, 'Uzbekistan’s 2030 Strategy', 'Guest Talk highlights', '<p>MDIST Business Incubator and lecturer <strong>Abbos Utkirov</strong> hosted a guest lecture by \n<strong>Eldor Tulyakov</strong>, focusing on economic development and its impact on entrepreneurship and innovation.</p>\n\n<p>During this exclusive guest lecture, Mr. Eldor Tulyakov delved into the key priorities of \n<strong>Uzbekistan’s 2030 Strategy</strong>. In this insightful session, he discussed critical aspects of national \ndevelopment with students, including:</p>\n\n<h3>Uzbekistan-2030 Strategy: Key Priorities</h3>\n<ul>\n    <li><strong>Empowering People –</strong> Creating conditions for individuals to reach their full potential.</li>\n    <li><strong>Economic Growth –</strong> Ensuring sustainable development and prosperity.</li>\n    <li><strong>Environmental Protection –</strong> Conserving water resources and promoting sustainability.</li>\n    <li><strong>Good Governance –</strong> Strengthening the rule of law and public administration.</li>\n    <li><strong>Peace & Security –</strong> Upholding stability and a safe society.</li>\n</ul>\n\n<p>This strategy aims to drive progress and innovation for a better future.</p>\n\n<p>\n    <strong>\n        <a href=\"https://www.mdis.uz/en/news/gostevaja-lektsija-po-ekonomicheskomu-razvitiju-s-eldorom-tuljakovym-v-biznes-inkubatore-mdist\" target=\"_blank\">\n            Find out more on MDIST Official Website\n        </a>\n    </strong>\n</p>\n\n<p>\n    🌐 <a href=\"https://brightbridge.uz\" target=\"_blank\">BRIGHTBRIDGE.UZ</a> <br>\n    🖥 <a href=\"https://brightbridge.uz/logup\" target=\"_blank\">Register now</a> and shape your future with us!\n</p>\n\n<p>\n    📱 <a href=\"https://t.me/jobcare.uz/\" target=\"_blank\">Telegram</a> <br>\n    📱 <a href=\"https://instagram.com/brightbridge\" target=\"_blank\">Instagram</a> <br>\n    📱 <a href=\"https://linkedin.com/company/brightbridge\" target=\"_blank\">LinkedIn</a>\n</p>\n\n<p>✉️ <a href=\"mailto:brightbridge_support@gmail.com\">@brightbridge_support</a></p>\n', 'upl/blog/1741117068_sssthumb.png', 'https://www.youtube.com/watch?v=_QfbzBqaTwk', 5, '2025-03-04 19:37:48', '2025-03-04 19:37:48'),
(21, 'MDIST rektori Ilhom Mamatqulov bilan suhbat! | Albatta ko\'ring', 'Ushbu video Toshkentdagi Singapur menejmentni rivojlantirish instituti (MDIST) rektori Ilhom Mamatqulov bilan suhbatni o\'z ichiga oladi.', 'Suhbat davomida u institutning rivojlanish strategiyasi, ta\'lim dasturlari va talabalarga yaratilayotgan imkoniyatlar haqida so\'z yuritadi. Shuningdek, Ilhom Mamatqulovning shaxsiy tajribasi va MDISTdagi faoliyati haqida ham ma\'lumotlar beriladi. ​\r\n\r\nIlhom Mamatqulov 2023-yil 1-martda MDIST rektori lavozimiga tayinlangan bo\'lib, iqtisodiyot va moliya sohasida keng tajribaga ega. U Toshkentdagi Vestminster xalqaro universitetida iqtisod bo\'yicha bakalavr, Uels universitetida bank va moliya magistri, Aberdin universitetida iqtisodiyot fanlari doktori darajalarini olgan. Shuningdek, u O\'zbekiston Respublikasi iqtisodiyot va moliya vazirligi huzuridagi prognozlash va makroiqtisodiy tadqiqotlar institutida faoliyat yuritgan. ​\r\nmdis.uz\r\n\r\nMDIST rektori sifatida Ilhom Mamatqulov institutni qayta tashkil etish, yangi loyihalarni amalga oshirish, xodimlar va professor-o\'qituvchilarni rag\'batlantirish, gender tenglikka e\'tibor qaratish kabi tashabbuslarni amalga oshirmoqda. Shuningdek, u Britaniya universitetlari bilan hamkorlikni rivojlantirish, yangi ta\'lim yo\'nalishlarini joriy etish va talabalarga qo\'shimcha imkoniyatlar yaratish ustida', 'upl/blog/1741294977_maxresdefault.jpg', 'https://www.youtube.com/watch?v=43OBLmrMf-M&t=33s', 5, '2025-03-06 21:02:57', '2025-03-06 21:02:57'),
(22, 'A Job Interview Training', 'Key Takeaways', '✅ Research the Company & Role – Understand expectations and align your responses.<br>\n✅ Polish Your CV & Cover Letter – Ensure they are well-structured and tailored.<br>\n✅ Practice Common Questions – Use the STAR method for strong answers.<br>\n✅ Improve Communication & Body Language – Speak confidently and professionally.<br>\n✅ Dress for Success – Make a great first impression.<br>\n✅ Follow-Up Effectively – Send a professional thank-you email.<br>\n✅ Mock Interview Session – Practice real interviews and get feedback.<br>\n\n💡 Gain confidence, refine your approach, and boost your job interview success!<br>\n\n<p><strong>\n    <a href=\"https://www.mdis.uz/en/news/gostevaja-lektsija-po-ekonomicheskomu-razvitiju-s-eldorom-tuljakovym-v-biznes-inkubatore-mdist\" target=\"_blank\">\n        Find out more on MDIST Official Website\n    </a>\n</strong></p>\n\n<p>🌐 <a href=\"https://brightbridge.uz\" target=\"_blank\">BRIGHTBRIDGE.UZ</a> <br>\n🖥 <a href=\"https://brightbridge.uz/logup\" target=\"_blank\">Register now</a> and shape your future with us!\n</p>\n\n<p>📱 <a href=\"https://t.me/jobcare.uz/\" target=\"_blank\">Telegram</a> <br>\n📱 <a href=\"https://instagram.com/brightbridge\" target=\"_blank\">Instagram</a> <br>\n📱 <a href=\"https://linkedin.com/company/brightbridge\" target=\"_blank\">LinkedIn</a>\n</p>\n\n<p>✉️ <a href=\"mailto:brightbridge_support@gmail.com\">@brightbridge_support</a></p>\n', 'upl/blog/1741801667_photo_2025-03-12_22-46-40.jpg', '0', 1, '2025-03-12 17:47:47', '2025-03-12 17:50:10'),
(23, 'Job Interview Workshop', 'Highlights', '<p>Training offers a brief clip showcasing key moments and insights from a job interview. \nIt likely includes tips or examples of effective answers and strategies for a successful interview. \nYou can watch the full clip on <strong>14th of March, 2025</strong>. \nKeep visiting <a href=\"https://brightbridge.uz\" target=\"_blank\">brightbridge.uz</a>.</p>\n\n💡 Gain confidence, refine your approach, and boost your job interview success!<br>\n\n<p>\n    <strong>\n        <a href=\"https://www.mdis.uz/en/news/gostevaja-lektsija-po-ekonomicheskomu-razvitiju-s-eldorom-tuljakovym-v-biznes-inkubatore-mdist\" target=\"_blank\">\n            Find out more on MDIST Official Website\n        </a>\n    </strong>\n</p>\n\n<p>\n    🌐 <a href=\"https://brightbridge.uz\" target=\"_blank\">BRIGHTBRIDGE.UZ</a> <br>\n    🖥 <a href=\"https://brightbridge.uz/logup\" target=\"_blank\">Register now</a> and shape your future with us!\n</p>\n\n<p>\n    📱 <a href=\"https://t.me/jobcare.uz/\" target=\"_blank\">Telegram</a> <br>\n    📱 <a href=\"https://instagram.com/brightbridge\" target=\"_blank\">Instagram</a> <br>\n    📱 <a href=\"https://linkedin.com/company/brightbridge\" target=\"_blank\">LinkedIn</a>\n</p>\n\n<p>✉️ <a href=\"mailto:brightbridge_support@gmail.com\">@brightbridge_support</a></p>\n', 'upl/blog/1741801829_IMG_6994.PNG', 'https://youtube.com/shorts/WruGLag9E9o?si=wPRlOva4CJfSEJ7S', 1, '2025-03-12 17:50:30', '2025-03-12 19:17:28'),
(24, 'MBTI (Myers-Briggs Type Indicator) Workshop conducted by Ernst & Young', 'Join', '<h2> Training: Understanding Yourself and Others through MBTI </h2> <p><strong>Dear Students,</strong></p> <p> We are thrilled to announce a unique event dedicated to MBTI Testing organized by EY! </p> <p> <strong>📅 Date:</strong> 25th March, 2025 <br> <strong>⏰ Time:</strong> 14:00 <br> <strong>📍 Venue:</strong> B412 Business Incubator<br> <strong>👔 Dress Code:</strong> Formal or Semi-formal </p> <h3> During this event, you will learn how the MBTI test can help you better understand your strengths and weaknesses, as well as the dynamics of your interactions with others. This is a fantastic opportunity for personal growth and improving teamwork! <a href=\" https://forms.gle/RavnZHYidgznvLhW9 \" target=\"_blank\"> Register here </a> and shape your future with us! </p> <p> <a href=\"https://www.mdis.uz/en/news/business-communication-workshop-for-intern-fair-day-preparation\" target=\"_blank\"> 🌍 Find out more on MDIST Official Website </a> </p> <p> 🌐 <a href=\"https://brightbridge.uz\" target=\"_blank\">BRIGHTBRIDGE.UZ</a> <br> </p> <p> 📱 <a href=\"https://t.me/PDC_MDIST\" target=\"_blank\"> PDC Telegram</a> <br> 📱 <a href=\"https://t.me/jobcare.uz/\" target=\"_blank\">Brightbridge Telegram</a> <br> 📱 <a href=\"https://instagram.com/brightbridge\" target=\"_blank\">Instagram</a> <br> 📱 <a href=\"https://linkedin.com/company/brightbridge\" target=\"_blank\">LinkedIn</a> </p> <p>', 'upl/blog/1742975922_111111111111111111111111111111111111111photo_2025-03-24_14-19-02.jpg', '0', 1, '2025-03-26 07:58:42', '2025-03-26 07:59:48'),
(25, 'Training: Inter-University Startup Incubator', 'Transform your idea into Startup', '<h2> Training: Inter-University Startup Incubator </h2> <p><strong>Dear Students,</strong></p> <p> Exciting Opportunity for Students and Graduates of Management Development Institute of Singapore in Tashkent ! </p> <p> <strong> Program Dates:</strong> 15th May, 2025 <br> <strong>Format:</strong> Hybrid (Online & Offline)<br> <strong>Who Can Apply?:</strong> Students and Graduates of Management Development Institute of Singapore in Tashkent<br> <strong>👔 Dress Code:</strong> Formal or Semi-formal </p> <h3> We\'re thrilled to announce the launch of Inter-University Incubator Program, a one-of-a-kind startup incubation program designed exclusively for the students and alumni of Management Development Institute of Singapore in Tashkent! This hybrid program will run from May 15 to August 15, offering you a chance to bring your startup ideas to life with expert mentorship, hands-on workshops, and networking opportunities with top industry leaders. If you\'re passionate about innovation and eager to turn your idea into a successful business, this is the perfect chance for you! Key Highlights: - 22 Training Sessions - 12 Traction Sessions - Demo Day - Expert mentorship & more! <a href=\" https://forms.gle/fBZHYEigjdX9QkbKA\" target=\"_blank\"> Register here </a> and shape your future with us! </p> <p> <a href=\"https://www.mdis.uz/en/news/business-communication-workshop-for-intern-fair-day-preparation\" target=\"_blank\"> 🌍 Find out more on MDIST Official Website </a> </p> <p> 🌐 <a href=\"https://brightbridge.uz\" target=\"_blank\">BRIGHTBRIDGE.UZ</a> <br> </p> <p> 📱 <a href=\"https://t.me/mdist_business\" target=\"_blank\"> Business Incubation Centre Telegram</a> <br> 📱 <a href=\"https://t.me/jobcare.uz/\" target=\"_blank\">Brightbridge Telegram</a> <br> 📱 <a href=\"https://instagram.com/brightbridge\" target=\"_blank\">Instagram</a> <br> 📱 <a href=\"https://linkedin.com/company/brigh